xpath.script:
document.addEventListener('DOMContentLoaded', function() {
    document.querySelectorAll('[data-rappel-trigger]').forEach(function(btn) {
        btn.addEventListener('click', function(e) {
            e.preventDefault();
            document.getElementById('ssRappelModal').style.display = 'flex';
        });
    });
    document.querySelectorAll('[data-rappel-close]').forEach(function(btn) {
        btn.addEventListener('click', function() {
            document.getElementById('ssRappelModal').style.display = 'none';
        });
    });
    document.getElementById('ssRappelModal').addEventListener('click', function(e) {
        if (e.target === this) this.style.display = 'none';
    });
});
